<script setup lang="ts">
import ResourceRecovery from './ResourceRecovery.vue';
import RenderSettingsPanel from './RenderSettingsPanel.vue';
import { defaultRenderSettings } from '#/api/creative-video/render-settings';
import { refreshFinance, applyFinance } from '#/api/creative-video/server-finance';
import { proposeRevision, applyRevision } from '#/api/creative-video/revision';
import type { RevisionPlan } from '#/api/creative-video/revision';
import { timelineSrt } from '#/api/creative-video/export';
import { modelApi, capabilityIssue } from '#/api/creative-video/models';
import type { ModelCapability } from '#/api/creative-video/models';
import { resourceApi } from '#/api/creative-video/resources';
import { splitBeatsToShots } from '#/api/creative-video/story';
import { studioStorage } from '#/api/creative-video/storage';
import { recordRevision, restoreRevision, addShot, removeShot, splitShot, mergeShot } from '#/api/creative-video/shots';
import { timelineDuration, approveStoryboard, approveShot, rejectShot } from '#/api/creative-video/timeline';
import { attachReference, selectedReference } from '#/api/creative-video/media';
import { useRoute } from 'vue-router';
import { onMounted } from 'vue';
import { brandApi, modelDefaults } from '#/api/creative-video/settings';
import { generationApi } from '#/api/creative-video/generation';
import MockVideoPlayer from './MockVideoPlayer.vue';
import VersionCompare from './VersionCompare.vue';
import AnimaticPlayer from './AnimaticPlayer.vue';
import { allowed, authorize } from '#/api/creative-video/permissions';
import { computed, onUnmounted, ref, watch } from 'vue';
import { ElButton, ElInput, ElInputNumber, ElMessage, ElMessageBox, ElTag } from 'element-plus';
import { isRenderOutdated, loadProduction, persist, settle } from '#/api/creative-video/production';
import type { Shot } from '#/api/creative-video/production';
const route=useRoute();onMounted(()=>{const id=route.query.shot;if(id)document.getElementById(`shot-${id}`)?.scrollIntoView({block:'center'});});
const props=defineProps<{projectId:number;duration:number;stage:number}>();
const state=ref(loadProduction(props.projectId,props.duration));
state.value.shots.forEach(recordRevision);state.value.renderSettings??=defaultRenderSettings(props.duration);
watch(()=>JSON.stringify(state.value.shots.map(s=>[s.id,s.revision,s.adopted,s.seconds,s.overlap])),()=>{if(state.value.renderSettings)state.value.renderSettings.checks={story:false,brand:false,truth:false,audio:false};});
function editStructure(action:()=>void){try{action();studioStorage.removeItem(`storyboard-approved-${props.projectId}`);save();}catch(e){ElMessage.warning((e as Error).message);}}
async function uploadReference(s:Shot,event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;try{await attachReference(s,file);revise(s);}catch(e){ElMessage.warning((e as Error).message);}}
const defaults=modelDefaults();const brand=ref(brandApi.load());
const capabilities=ref<ModelCapability[]>([]);const aspect=ref('9:16');const capability=computed(()=>capabilities.value.find(c=>c.id===model.value));void modelApi.list().then(data=>capabilities.value=data).catch(()=>ElMessage.warning('模型能力读取失败，请重新打开页面'));
const model=ref<'standard'|'premium'>(defaults.model);const resolution=ref<'720p'|'1080p'>(defaults.resolution);const candidates=ref(1);const failedCandidates=ref(0);
const selectedRender=ref<number>();
const timeout=ref(false);const failing=ref(false);const feedback=ref('');const selected=ref(1);const proposal=ref<RevisionPlan>();
const total=computed(()=>timelineDuration(state.value.shots));
const previewShots=computed(()=>{if(props.stage!==7)return state.value.shots;const successful=state.value.renders.filter(r=>!r.status||r.status==='success');const r=successful.find(r=>r.id===selectedRender.value)||successful.at(-1);if(!r)return [];return (JSON.parse(r.shots) as {id:number;prompt?:string;seconds:number;overlap?:number;referenceImage?:string}[]).map(s=>({id:s.id,text:s.prompt||'旧版模拟快照',seconds:s.seconds,overlap:s.overlap,referenceImage:s.referenceImage}));});
const ready=computed(()=>state.value.shots.every(s=>s.versions.some(v=>v.id===s.adopted&&!v.rejected)));
async function syncScript(){
 if(!allowed('edit'))return;
 const script=JSON.parse(studioStorage.getItem(`vidcraft-script-${props.projectId}`)||'{}') as {beats?:{text:string;seconds:number}[]};
 if(!script.beats?.length){ElMessage.warning('请先生成剧本');return;}
 if(state.value.jobs.some(j=>j.status==='running')){ElMessage.warning('请等待生成任务完成或取消任务');return;}
 try{await ElMessageBox.confirm('将按新节拍更新分镜并清除采用状态。历史候选、任务、账单与成片保留。','更新分镜');}catch{return;}
 const shots=state.value.shots;const planned=splitBeatsToShots(script.beats);planned.forEach((b,i)=>{const existing=shots[i];if(existing){existing.text=b.text;existing.seconds=b.seconds;existing.narration=b.text;existing.subtitle=b.text;existing.revision++;recordRevision(existing);}else shots.push({id:Math.max(0,...shots.map(s=>s.id))+1,text:b.text,seconds:b.seconds,revision:1,versions:[]});});
 if(shots.length>planned.length){ElMessage.info('旧剧本额外镜头保留，请人工核对总时长');}
 studioStorage.removeItem(`storyboard-approved-${props.projectId}`);save();
}
const storyboardStatus=ref('本地分镜');const storyboardSaving=ref(false);
function storyboardPayload(){return {targetSeconds:props.duration,shots:state.value.shots.map(({versions:_versions,references:_references,...shot})=>shot)};}
async function saveStoryboard(confirm=false){if(storyboardSaving.value)return false;storyboardSaving.value=true;studioStorage.removeItem(`storyboard-approved-${props.projectId}`);const payload=storyboardPayload();const fingerprint=JSON.stringify(payload);try{const record=await resourceApi.save(props.projectId,'storyboard',payload,confirm);if(JSON.stringify(storyboardPayload())!==fingerprint){storyboardStatus.value='分镜在同步期间变化，请重新保存';return false;}storyboardStatus.value=`服务端分镜 R${record.revision} ${record.confirmed?'已确认':'草稿已保存'}`;if(confirm)studioStorage.setItem(`storyboard-approved-${props.projectId}`,'true');save();return true;}catch{storyboardStatus.value='分镜同步失败或冲突，本地内容保留';ElMessage.warning(storyboardStatus.value);return false;}finally{storyboardSaving.value=false;}}
async function approve(){try{approveStoryboard(state.value.shots,props.duration);}catch(e){ElMessage.warning((e as Error).message);return;}save();if(await saveStoryboard(true))ElMessage.success('服务端分镜已确认');}

function save(){try{persist(props.projectId,state.value);}catch(e){ElMessage.warning((e as Error).message);state.value=loadProduction(props.projectId,props.duration);}}
const financeStatus=ref<'connecting'|'online'|'offline'>('connecting');const financeReset=ref(false);let refreshing=false;async function refresh(){if(refreshing)return;refreshing=true;try{financeReset.value=(await refreshFinance(props.projectId,state.value))||financeReset.value;financeStatus.value='online';settle(state.value);save();}catch{financeStatus.value='offline';}finally{refreshing=false;}}
void refresh();const timer=setInterval(()=>void refresh(),1000);
async function financeAction(action:'cancel'|'reconcile'|'topup',options:{jobId?:number;outcome?:'success'|'failed';amount?:number}){try{applyFinance(props.projectId,state.value,await generationApi.action(action,props.projectId,options));save();}catch(e){ElMessage.warning((e as Error).message);}}
onUnmounted(()=>clearInterval(timer));
async function request(s:Shot){const issue=capabilityIssue(capability.value,s.seconds,resolution.value,aspect.value);if(issue){ElMessage.warning(issue);return;}if(financeStatus.value!=='online'){ElMessage.warning('服务连接不可用，请先恢复连接再提交');return;}if(s.approvedRevision!==s.revision){ElMessage.warning('当前分镜修订尚未审核，请返回图文分镜确认');return;}let quote;try{quote=await generationApi.quote(s,model.value,resolution.value,candidates.value,aspect.value);await ElMessageBox.confirm(`镜头 ${s.id} · 修订 R${s.revision} · ${quote.model} 演示模型 · ${quote.resolution} · ${quote.candidates} 个候选 · ${s.seconds} 秒\n预计 ${quote.cost} 积分，可用 ${state.value.balance}，冻结后 ${state.value.balance-quote.cost}。报价有效期 60 秒，自动重试 0 次。\n仅生成当前镜头，不覆盖旧视频。成功后不满意，重新生成需再次付费。未知结果等待核对。`,'生成报价',{confirmButtonText:'确认冻结并生成'});}catch{return;}try{if(!quote)return;if(state.value.balance<quote.cost)throw new Error('可用积分不足，请充值或调整参数');await generationApi.submit({...s,referenceImage:selectedReference(s)?.dataUrl},quote.id,`project-${props.projectId}-quote-${quote.id}`,props.projectId,failing.value,timeout.value,Math.min(failedCandidates.value,candidates.value));await refresh();}catch(e){ElMessage.warning((e as Error).message);await refresh();}}
function revise(s:Shot){s.revision++;s.approvedRevision=undefined;recordRevision(s);studioStorage.removeItem(`storyboard-approved-${props.projectId}`);save();}
async function reviewVersion(shotId:number,versionId:number,action:'adopt'|'reject'){try{await generationApi.review(props.projectId,shotId,versionId,action,state.value.reviewRevisions?.[shotId]??0);await refresh();}catch{ElMessage.warning('审核失败或版本已变化，已刷新候选，请重新比较后审核');await refresh();}}
async function reviewSingle(s:Shot){try{approveShot(s);save();await saveStoryboard(false);}catch(e){ElMessage.warning((e as Error).message);}}
async function returnShot(s:Shot){try{const result=await ElMessageBox.prompt('填写需要修改的内容','退回分镜');rejectShot(s,result.value);studioStorage.removeItem(`storyboard-approved-${props.projectId}`);save();await saveStoryboard(false);}catch(e){if(e instanceof Error)ElMessage.warning(e.message);}}
function move(index:number){const shots=state.value.shots;const previous=shots[index-1];const current=shots[index];if(previous&&current){shots[index-1]=current;shots[index]=previous;save();}}
function propose(){try{proposal.value=proposeRevision(state.value,selected.value,feedback.value);}catch(e){ElMessage.warning((e as Error).message);}}
function apply(){if(!proposal.value)return;try{applyRevision(state.value,proposal.value);studioStorage.removeItem(`storyboard-approved-${props.projectId}`);save();proposal.value=undefined;}catch(e){ElMessage.warning((e as Error).message);}}
async function render(){if(!state.value.renderSettings)return;try{await generationApi.render(props.projectId,state.value.shots.map(s=>({id:s.id,version:s.adopted!,seconds:s.seconds,overlap:s.overlap,narration:s.narration,subtitle:s.subtitle})),state.value.renderSettings,`render-${props.projectId}-${Date.now()}`);await refresh();ElMessage.success('服务端模拟合成任务已提交');}catch(e){ElMessage.warning((e as Error).message);await refresh();}}
function downloadSubtitles(){authorize('export');const successful=state.value.renders.filter(r=>!r.status||r.status==='success');const r=successful.find(r=>r.id===selectedRender.value)||successful.at(-1);if(!r)return;const shots=JSON.parse(r.shots) as {seconds:number;overlap?:number;subtitle?:string;prompt?:string}[];const url=URL.createObjectURL(new Blob([timelineSrt(shots)],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`演示时间线-${r.id}.srt`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function download(){authorize('export');const blob=new Blob([JSON.stringify(state.value.renders.filter(r=>!r.status||r.status==='success'),null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='模拟成片记录.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
</script>
<template>
 <div><ResourceRecovery v-if="stage===4" :project-id="projectId" kind="storyboard"/><p role="status">任务与钱包服务：{{ financeStatus==='online'?'已连接':financeStatus==='offline'?'连接中断，已暂停新生成提交':'正在连接' }} <ElButton v-if="financeStatus!=='online'" @click="refresh">重新连接</ElButton></p><p v-if="financeReset" role="alert">Mock 服务已重置。旧任务和流水已归档，原有候选与成片保留；当前余额以新服务为准。</p><details v-if="state.financeArchives?.length"><summary>服务重置前的历史记录（只读，不参与当前余额）</summary><div v-for="a in state.financeArchives" :key="a.instance"><p>{{ a.instance }} · {{ a.archivedAt }} · 原余额 {{ a.balance }}</p><p v-for="j in a.jobs" :key="j.id">任务 #{{ j.id }} · 镜头 {{ j.shotId }} · {{ j.status }}</p><p v-for="(l,i) in a.ledger" :key="i">{{ l.kind }} · {{ l.amount }} 积分 · {{ l.reason }}</p></div></details><details><summary>全片视觉规范 · {{ brand.name }} · R{{ brand.revision }}</summary><p>{{ brand.characters }}</p><p>{{ brand.scenes }}</p><p>{{ brand.visualStyle }} · {{ brand.voice }}</p><p>{{ brand.forbidden }}</p></details><h2>{{ ['图文分镜','动态预演','镜头视频','最终合成'][stage-4] }}</h2><p>总时长 {{ total }} 秒 · 可用 {{ state.balance }} 积分 · 冻结 {{ state.jobs.filter(j=>(j.status==='running'||j.status==='reconciling')).reduce((n,j)=>n+j.cost,0) }} 积分</p>
 <label v-if="stage===7">预览合成历史<select v-model="selectedRender"><option v-for="r in state.renders.filter(r=>!r.status||r.status==='success')" :key="r.id" :value="r.id">成片 #{{ r.id }} · {{ r.date }}</option></select></label><AnimaticPlayer v-if="stage===5 || stage===7" :shots="previewShots"/>
 <p v-if="stage===4" role="status">{{ storyboardStatus }}</p><ElButton v-if="stage===4" :loading="storyboardSaving" :disabled="!allowed('edit') || storyboardSaving" @click="saveStoryboard(false)">保存服务端分镜草稿</ElButton><ElButton v-if="stage===4" :disabled="!allowed('edit')" @click="syncScript">按当前剧本更新分镜</ElButton><ElButton v-if="stage===4" :disabled="!allowed('review')" type="primary" @click="approve">确认当前分镜</ElButton><div v-if="stage===6"><label>模型 <select v-model="model"><option value="standard">示例模型 A · 3积分/秒</option><option value="premium">示例模型 B · 5积分/秒</option></select></label><label>清晰度 <select v-model="resolution"><option :disabled="!capability?.resolutions.includes('720p')">720p</option><option :disabled="!capability?.resolutions.includes('1080p')">1080p</option></select></label><label>画幅<select v-model="aspect"><option v-for="a in ['9:16','16:9','1:1']" :key="a" :disabled="!capability?.supportedAspectRatios.includes(a)">{{ a }}</option></select></label><p>模型能力：{{ capability?.supportedDurationsSeconds.join('/') }} 秒 · 首帧 {{ capability?.supportsStartFrame?'支持':'不支持' }} · 尾帧 {{ capability?.supportsEndFrame?'支持':'不支持' }} · 延展 {{ capability?.supportsVideoExtension?'支持':'不支持' }} · 原生音频 {{ capability?.supportsNativeAudio?'支持':'不支持' }}（仅Mock元数据）</p><label>候选数量 <ElInputNumber v-model="candidates" :min="1" :max="3"/></label><label>模拟失败候选数<ElInputNumber v-model="failedCandidates" :min="0" :max="candidates"/></label><label><input v-model="failing" type="checkbox"/> 模拟生成失败（自动释放积分）</label><label><input v-model="timeout" type="checkbox"/> 模拟超时（等待费用核对）</label></div>
 <article :id="`shot-${s.id}`" v-for="(s,i) in state.shots" :key="s.id"><div class="shot-head"><b>镜头 {{ String(s.id).padStart(2,'0') }} · 修订 R{{ s.revision }}</b><ElTag>{{ s.adopted?'已采用候选':'待审核' }}</ElTag></div><div class="reference"><img v-if="selectedReference(s)" :src="selectedReference(s)?.dataUrl" :alt="selectedReference(s)?.name" style="max-height:220px;max-width:100%;margin:auto"/><template v-else>▧<small>尚未选择参考图</small></template></div><label>添加本地参考图（PNG/JPEG/WebP，1 MB以内）<input type="file" accept="image/png,image/jpeg,image/webp" :disabled="!allowed('edit')" @change="uploadReference(s,$event)"/></label><select v-if="s.references?.length" v-model="s.referenceId" :disabled="!allowed('edit')" @change="revise(s)"><option v-for="r in s.references" :key="r.id" :value="r.id">参考图 V{{ r.id }} · {{ r.name }}</option></select><ElInput :disabled="!allowed('edit')" v-model="s.text" type="textarea" @change="revise(s)"/><div class="shot-fields"><label v-for="field in (['narration','subtitle','motion','transition','music'] as const)" :key="field">{{ {narration:'旁白',subtitle:'字幕',motion:'镜头运动',transition:'转场',music:'背景音乐'}[field] }}<ElInput v-model="s[field]" :disabled="!allowed('edit')" @change="revise(s)"/></label></div><ElInputNumber :disabled="!allowed('edit')" v-model="s.seconds" :min="1" :max="20" @change="revise(s)"/> 秒 <label>转场重叠秒数<ElInputNumber v-model="s.overlap" :disabled="!allowed('edit') || i===state.shots.length-1" :min="0" :max="Math.max(0,s.seconds-1)" @change="revise(s)"/></label><div v-if="stage===4"><ElTag :type="s.approvedRevision===s.revision?'success':'warning'">{{ s.approvedRevision===s.revision?'当前修订已确认':'待审核 / 需复核' }}</ElTag><ElButton :disabled="!allowed('review')" @click="reviewSingle(s)">确认此镜头</ElButton><ElButton :disabled="!allowed('review')" @click="returnShot(s)">退回修改</ElButton><p v-if="s.reviewComment">审核意见：{{ s.reviewComment }}</p></div><ElButton v-if="i>0" :disabled="!allowed('edit')" @click="move(i)">上移</ElButton><ElButton v-if="stage>=6" :disabled="!allowed('generate') || financeStatus!=='online'" @click="request(s)">生成视频 / 重新报价</ElButton><p v-if="stage>=6 && capabilityIssue(capability,s.seconds,resolution,aspect)" role="status">{{ capabilityIssue(capability,s.seconds,resolution,aspect) }}</p>
 <div v-if="stage===4 && allowed('edit')"><ElButton @click="editStructure(()=>addShot(state,i))">增加镜头</ElButton><ElButton @click="editStructure(()=>addShot(state,i,s))">复制</ElButton><ElButton @click="editStructure(()=>splitShot(state,i))">拆分</ElButton><ElButton @click="editStructure(()=>mergeShot(state,i))">合并下一镜</ElButton><ElButton @click="editStructure(()=>removeShot(state,s.id))">删除</ElButton></div><details><summary>分镜修订历史（{{ s.history?.length || 0 }}）</summary><div v-for="h in s.history" :key="h.revision"><b>R{{ h.revision }} · {{ h.seconds }} 秒</b><p>{{ h.text }}</p><ElButton :disabled="!allowed('edit')" @click="editStructure(()=>restoreRevision(s,h.revision))">恢复为新修订</ElButton></div></details><VersionCompare v-if="s.versions.length>1" :versions="s.versions" :adopted="s.adopted"/><div v-for="(v,vi) in s.versions" :key="v.id" class="version"><b>V{{ vi+1 }} · R{{ v.revision }}</b><MockVideoPlayer v-if="stage>=6" :src="v.videoUrl || '/mock-media/demo-a.mp4'"/><p>{{ v.prompt }}</p><ElButton :disabled="v.rejected || !allowed('review')" @click="reviewVersion(s.id,v.id,'adopt')">{{ s.adopted===v.id?'当前正式版本':'采用 / 回退（免费）' }}</ElButton><ElButton :disabled="!allowed('review')" @click="reviewVersion(s.id,v.id,'reject')">拒绝候选</ElButton><small v-if="v.rejected">已拒绝</small><small v-else-if="v.revision!==s.revision">历史修订，采用后将按该候选生成时的画面内容合成</small></div></article>
 <div class="assistant"><h3>AI 局部修改助手（规则模拟）</h3><ElInputNumber v-model="selected" :min="1" :max="state.shots.length"/><ElInput v-model="feedback" placeholder="描述镜头的改动，例如纸张先破碎再出现人物"/><ElButton :disabled="!feedback.trim()" @click="propose">提出修改计划</ElButton><div v-if="proposal"><p>意图：{{ proposal.intent }} · 范围：{{ proposal.scope }} · {{ proposal.rationale }}</p><div v-for="c in proposal.changes" :key="c.shotId"><b>镜头 {{ c.shotId }} · {{ c.field }} · R{{ c.revision }}</b><p>修改前：{{ c.before }}</p><p>修改后：{{ c.after }}</p></div><p>保留：{{ proposal.preservedFields.join('、') }}</p><p>{{ proposal.requiresNewVideo?'需要重新生成画面，另行报价授权':'仅更新音频或字幕文本，不要求重新生成画面' }}</p><p v-for="u in proposal.uncertainties" :key="u">{{ u }}</p><ElButton :disabled="!allowed('edit')" @click="apply">应用修改，不扣费</ElButton><ElButton @click="proposal=undefined">放弃计划</ElButton></div></div>
 <div v-if="stage===7"><RenderSettingsPanel :production="state" :settings="state.renderSettings!"/><MockVideoPlayer v-if="state.renders.some(r=>r.status==='success')" src="/mock-media/demo-a.mp4" label="预置合成示例（不是实际时间线合成）"/><ElButton type="primary" :disabled="!ready || !allowed('export')" @click="render">合成模拟快照</ElButton><ElButton :disabled="!state.renders.some(r=>!r.status||r.status==='success') || !allowed('export')" @click="download">导出模拟记录</ElButton><ElButton :disabled="!state.renders.some(r=>r.status==='success') || !allowed('export')" @click="downloadSubtitles">导出选定成片字幕 SRT</ElButton><p><a href="/mock-media/demo-a.mp4" download="预置演示片段.mp4">下载预置 MP4 示例（非项目成片）</a> · <a href="/mock-media/demo.srt" download="示例字幕.srt">下载 SRT 示例</a></p><p v-for="r in state.renders" :key="r.id">合成任务 #{{ r.id }} · {{ r.status || 'success' }} · {{ r.date }} · {{ isRenderOutdated(state,r)?'时间线已变化，需要重新合成':'与当前时间线一致' }} · 非真实 MP4</p></div>
 <ElButton :disabled="!allowed('generate') || financeStatus!=='online'" @click="financeAction('topup',{amount:100})">演示充值 +100（无真实支付）</ElButton><ElButton :disabled="!allowed('generate') || financeStatus!=='online'" @click="financeAction('topup',{amount:500})">演示充值 +500</ElButton><details><summary>审核审计记录</summary><p v-for="(e,i) in state.reviewAudit" :key="i">{{ e.date }} · {{ e.actor }} · 镜头{{ e.shotId }} · {{ e.action }} 候选#{{ e.versionId }} · 审核版本{{ e.revision }}</p></details><details><summary>任务中心（{{ state.jobs.length }}）与积分账单</summary><p v-for="j in state.jobs" :key="j.id">任务 #{{ j.id }} / 镜头 {{ j.shotId }} / {{ j.status }} · {{ j.stage || '历史任务' }} <ElButton v-if="j.status==='running'" @click="financeAction('cancel',{jobId:j.id})">申请取消并核对</ElButton><template v-if="j.status==='reconciling'"><ElButton @click="financeAction('reconcile',{jobId:j.id,outcome:'failed'})">模拟核对：未收费，释放</ElButton><ElButton @click="financeAction('reconcile',{jobId:j.id,outcome:'success'})">模拟核对：已交付，结算</ElButton></template></p><p v-for="(l,i) in state.ledger" :key="i">任务 #{{ l.jobId }} · {{ l.kind }} · {{ l.amount }} 积分</p></details>
 </div>
